:root {
--bs-font-sans-serif: $(body.text.family);
--bs-body-bg: $(body.background);
--bs-body-color: $(body.text.color);
--jt-primary: $(keycolor);
--jt-heading-color: $(posts.title.color);
--jt-heading-link: $(posts.title.color);
--jt-heading-hover: $(keycolor);
--jt-link-color: $(body.link.color);
--jt-link-hover: $(body.hover.color);
--jt-blockquote: $(posts.text.color);
--jt-btn-primary: $(posts.icons.color);
--jt-btn-primary-hover: $(labels.background.color);
--jt-btn-light-hover: $(posts.title.color);
--jt-border-light: $(border.color);
--jt-bg-light: #f3f7f9;
--jt-archive-bg: #ffffff;
--jt-nav-color: $(tabs.color);
--jt-nav-hover: $(tabs.hover);
--jt-nav-selected: $(tabs.selected.color);
--jt-dropdown-bg: $(dropdown.bg);
--jt-dropdown-color: $(dropdown.color);
--jt-dropdown-hover: $(dropdown.hover);
--jt-dropdown-selected: $(dropdown.selected);
--jt-header-bg: $(header.bg);
--jt-header-color: $(header.color);
--jt-header-border: $(header.border);
--jt-footer-bg: $(footer.bg);
--jt-footer-color: $(footer.color);
--jt-footer-link: $(footer.link);
--jt-footer-border: $(footer.border);
--jt-socket-bg: $(socket.bg);
--jt-socket-color: $(socket.color);
--gd-bg:linear-gradient(to left, #006cff 0%, #ff00c7 100%);
 --grdt:linear-gradient(135deg,#ff1a75 0%,#7d2ae8 40%,#00c4cc 95%);
--ftr:radial-gradient( circle at 20% 100%, rgba(184, 184, 184, 0.1) 0%, rgba(184, 184, 184, 0.1) 33%, rgba(96, 96, 96, 0.1) 33%, rgba(96, 96, 96, 0.1) 66%, rgba(7, 7, 7, 0.1) 66%, rgba(7, 7, 7, 0.1) 99% ), linear-gradient(40deg, #040a22, #162561, #202e64, #6f7aa6);
--heads:linear-gradient(45deg, #85FFBD 0%, #FFFB7D 100%);}
.dark-mode{
--jt-heading-hover:yellow;
--jt-primary:yellow;
--bs-body-bg:#09191d;
--bs-body-color: white;
--jt-heading-color:white;
--jt-heading-link:#fff;
--jt-btn-light-hover:hsl(210,11%,85%);
--jt-link-color:#00ff57;
--jt-border-light:gray;
--jt-bg-light:hsl(210,11%,20%);
--jt-archive-bg:transparent;
--jt-nav-color:#ffffff;
--jt-dropdown-bg:hsl(210,11%,18%);
--jt-dropdown-color:#ffffff;
--jt-header-bg:hsl(210,11%,15%);
--jt-header-color:#ffffff;
--jt-header-border:hsl(210,11%,20%);
--jt-footer-bg:hsl(210,11%,15%);
--jt-footer-color: white;
--jt-footer-border:hsl(210,11%,20%);
--jt-socket-bg: transparent;
--jt-socket-color:#ffffff;
--gd-bg:linear-gradient(45deg, rgb(255, 255, 0), rgb(0, 255, 255));
--heads:linear-gradient(to right, #6a11cb 0%, #2575fc 100%);
--grdt:black;
--ftr:radial-gradient(circle at 39% 47%, rgba(107, 107, 107,0.08) 0%, rgba(107, 107, 107,0.08) 33.333%,rgba(72, 72, 72,0.08) 33.333%, rgba(72, 72, 72,0.08) 66.666%,rgba(36, 36, 36,0.08) 66.666%, rgba(36, 36, 36,0.08) 99.999%),radial-gradient(circle at 53% 74%, rgba(182, 182, 182,0.08) 0%, rgba(182, 182, 182,0.08) 33.333%,rgba(202, 202, 202,0.08) 33.333%, rgba(202, 202, 202,0.08) 66.666%,rgba(221, 221, 221,0.08) 66.666%, rgba(221, 221, 221,0.08) 99.999%),radial-gradient(circle at 14% 98%, rgba(184, 184, 184,0.08) 0%, rgba(184, 184, 184,0.08) 33.333%,rgba(96, 96, 96,0.08) 33.333%, rgba(96, 96, 96,0.08) 66.666%,rgba(7, 7, 7,0.08) 66.666%, rgba(7, 7, 7,0.08) 99.999%),linear-gradient(45deg, rgb(97, 14, 117),rgb(20, 32, 127));
}

body {
font: $(body.text);
color: var(--bs-body-color);
background-color: var(--bs-body-bg);
line-height: 1.5;
-webkit-font-smoothing: antialiased;
-moz-osx-font-smoothing: grayscale;
text-rendering: optimizeLegibility;
font-size:15px;
font-family:Google Sans Text;
}
.d-block {
display:none;
}
.h1,.h2,.h3,.h4,.h5,.h6,
h1,h2,h3,h4,h5,h6 {
font: $(posts.title);
}
a {
transition-property: background-color, border-color, color, fill, stroke;
transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
transition-duration: .3s;
text-decoration: none;
color: var(--jt-link-color);
cursor:pointer;
}
a:hover {
color: var(--jt-link-hover);
}
.fs-7 {
font-size: 0.875rem;
}
.fs-8 {
font-size: 0.75rem;
}
.fs-9 {
font-size: 0.7rem;
}
.btn{
box-shadow: none !important
}
.btn-sm {
min-width: 32px;
min-height: 32px;
}
img,
svg,
iframe {
max-width:100%
}
img {
height:auto;
object-fit:cover;
}
label {
cursor: pointer;
}
.visually-hidden {
position: unset !important;
}
.form-control:focus {
box-shadow: none;
border-color: var(--jt-primary);
}
.form-control::placeholder {
opacity: .5;
}
.dropdown-toggle::after {
border-width: 0.25em 0.25em 0;
}
.dropdown-menu {
margin: 0;
padding: 0;
}
.px-3 {
padding-right: 1rem;
padding-left: 1rem;
}
.ratio:before{
content: none;
}
.ratio-1x1 {
padding-bottom: 100%;
}
.ratio-4x3 {
padding-bottom: 56.25%;
}
.ratio-16x9 {
padding-bottom: 56.25%;
}
.ratio-21x9 {
padding-bottom: 56.25%;
}
.object-cover {
object-fit: cover;
}
.jt-text-primary,
.hover-text-primary:hover,
input:checked ~ .check-text-primary {
color: var(--jt-primary)!important
}
.jt-btn-primary,
.jt-btn-outline-primary:hover {
color: #fff;
background-color: var(--jt-btn-primary);
border-color: var(--jt-btn-primary);
}
.jt-btn-light {
color: var(--bs-body-color);
background-color: var(--jt-bg-light);
border-color: var(--jt-bg-light);
}
.jt-btn-light:hover {
color: var(--jt-btn-light-hover);
}
.jt-btn-primary:hover,
.hover-btn-primary:hover,
input:checked + .jt-btn-outline-primary {
color: #fff !important;
background-color: var(--jt-btn-primary-hover)!important;
border-color: var(--jt-btn-primary-hover)!important
}
.jt-btn-outline-primary {
color: var(--jt-btn-primary);
border-color: var(--jt-btn-primary);
}
.jt-bg-primary {
background-color: var(--jt-primary)
}
.jt-bg-light {
background-color: var(--jt-bg-light)
}
.bg-archive {
background-color: var(--jt-archive-bg)
}
.jt-border-light {
border-color: var(--jt-border-light)!important;
}
input:checked ~ .d-block-check {
display: block !important;
}
input:checked ~ .d-none-check {
display: none !important;
}
.dropdown-menu,
.accordion-item,
.accordion-header {
background-color: var(--bs-body-bg);
color: var(--bs-body-color);
border-color: var(--jt-border-light);
}
.lazyload {
transition-property: opacity;
transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
transition-duration: .3s;
opacity: 0;
}
.lazyload.loaded {
opacity: 1;
}

/* JetTheme Style */

pre {
background-color: var(--jt-bg-light);
margin-bottom: 1rem;
padding: 1rem;
font-size: 0.75rem;
}
blockquote {
border-left:  5px solid var(--jt-blockquote);
color: inherit;
font-size: 1.125rem;
margin-bottom: 1.5rem;
margin-top: 1.5rem;
padding-left: 1rem;
}
.header-animate.header-hidden {
transform: translateY(-100%);
box-shadow: none !important;
}
#header {
background-color: var(--jt-header-bg);
color: var(--jt-header-color);
transition-property: transform;
transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
transition-duration: .3s;
min-height: 50px;
border-bottom: 1px solid var(--jt-header-border);
}

.jt-icon{
display: inline-block;
height: 1.2em;
vertical-align: -0.15em;
width: 1.2em;
}
/*.jt-icon-center {
font-family: sans-serif;
}*/
.icon-dark,
.dark-mode .icon-light {
display: none;
}
.dark-mode .icon-dark {
display: block;
}
#dark-toggler,
#search-toggler,
#navbar-toggler {
line-height: 1;
}
#dark-toggler {
font-size: 19px;
}
#footer {
background-color: var(--jt-footer-bg);
color: var(--jt-footer-color);
border-top: 1px solid var(--jt-footer-border);
}
#socket {
background-color: var(--jt-socket-bg);
color: var(--jt-socket-color);
}
#navbar {
z-index: 9999;
}
#navbar .menu-item {
position: relative;
}
#navbar .nav-link {
min-height: 40px;
}
#navbar .dropdown-toggle {
cursor: pointer;
align-items: center;
display: flex;
}
#navbar.d-block,
#navbar .dropdown-menu,
#navbar .nav-link,
#navbar .dropdown-toggle {
-webkit-transition: .3s;
-ms-transition: .3s;
-o-transition: .3s;
transition: .3s;
}
#navbar .navbar-nav > .menu-item > .nav-link {
font: $(tabs.font);
line-height: 1.5;
color: var(--jt-nav-color);
}
#navbar .navbar-nav > .menu-item:hover > .nav-link,
#navbar .navbar-nav > .menu-item:hover > .dropdown-toggle {
color: var(--jt-nav-hover);
}
#navbar .navbar-nav > .menu-item > .nav-link.active,
#navbar .navbar-nav > .menu-item > .active ~ .dropdown-toggle {
color: var(--jt-nav-selected);
}
.logo-wrap {
width: $(logo.width);
}
#search-header .dropdown-menu {
background-color:var(--jt-dropdown-bg);
color: var(--jt-dropdown-color);
border-color: var(--jt-header-border);
min-width: 300px;
right:0;
top:100%
}
.blog-admin {
display: none;
}
#pagination li + li {
margin-left: 5px;
}
.no-items {
display: none;
}
.feature-image,
.separator,
.tr-caption-container {
margin-bottom: 1rem;
}
.tr-caption-container {
width: 100%;
}
.separator a,
.tr-caption-container a {
margin: 0 !important;
padding: 0 !important;
}
.tr-caption {
font-size: 12px;
font-style: italic;
}
.widget:last-child {
margin-bottom: 0 !important;
}
#post-body .widget {
margin-top: 1.5rem;
}
.item-title {
color: var(--jt-heading-link);
}
.item-title:hover {
color: var(--jt-heading-hover);
}
#comment-editor{
width:100%
}
#primary .widget-title {
font-weight: 300;
text-transform: uppercase;
}
#footer .widget-title {
text-transform: uppercase;
}
#footer .widget-title,
#sidebar .widget-title {
font-size: 13px !important;
}
#footer .widget-title:after {
content: "";
display: block;
width: 50px;
border-bottom: 2px solid var(--jt-primary);
margin-top: 10px;
}
#primary .widget-title > span {
background-color: var(--bs-body-bg);
padding-right: 5px;
position: relative;
}
#main .widget-title:before,
#sidebar .widget-title:before {
background-color:  var(--jt-bg-light);
content: "";
height: 1px;
display: block;
position: absolute;
top: 50%;
transform: translateY(-50%);
width: 100%;
}
#main .widget-title:before {
border-right: 30px solid var(--jt-primary);
height: 5px;
}
.send-success:not(.loading) .contact-form-msg,
.send-error:not(.loading) .contact-form-msg {
display:block !important;
}
.send-success .contact-form-msg{
border-color: rgba(25,135,84,.3) !important;
}
.send-error .contact-form-msg{
border-color: rgba(255,193,7,.3) !important;
}
.send-success .contact-form-msg:before{
content: attr(data-success);
}
.send-error .contact-form-msg:before{
content: attr(data-error);
}
hr.example-ads:before {
content: "Advertisement here";
}
hr.example-ads {
background-color: var(--jt-bg-light);
border-radius: 0.25rem;
font-size: 0.875rem;
height: auto;
margin: 0;
opacity: 1;
padding: 1.5rem 0;
text-align: center;
}
body > .google-auto-placed {
margin: 0 auto 1.5rem;
max-width: 1108px;
}
.google-auto-placed > ins {
margin: 0 !important;
}
font{background:transparent!important;box-shadow:none!important}
.goog-te-gadget-simple img,.goog-te-gadget-simple .VIpgJd-ZVi9od-xl07Ob-lTBxed span,#goog-gt-tt,.VIpgJd-ZVi9od-ORHb-OEVmcd{display:none!important}
iframe.skiptranslate{border-left:none!important;border-top:none!important;border-bottom:none!important;border-right:none!important;border:none;box-shadow:none}
.goog-te-gadget-simple{background-color:transparent!important;background:url("https://upload.wikimedia.org/wikipedia/commons/d/d7/Google_Translate_logo.svg") center / 12px no-repeat;-webkit-transition:all .2s ease;transition:all .2s ease;background-size: 20px 20px;display:inline-block;font-weight:400;line-height: 1.8;padding:0 6px;text-align:center;white-space:nowrap;vertical-align: middle;-ms-touch-action: manipulation;touch-action:manipulation;cursor:pointer;-webkit-user-select: none;-moz-user-select:none;-ms-user-select:none;user-select:none;border-left:none!important;border-top:none!important;border-bottom:none!important;border-right:none!important;border-radius: 4px}

.dark-mode .goog-te-gadget-simple{background-color:transparent!important;background:url("https://upload.wikimedia.org/wikipedia/commons/d/d7/Google_Translate_logo.svg") center / 12px no-repeat;-webkit-transition:all .2s ease;transition:all .2s ease;background-size: 20px 20px;}

/* TYPOGRAPY */

.h1,h1{font-size:calc(1.375rem + 1.5vw)}
.h2,h2{font-size:calc(1.325rem + .9vw)}
.h3,h3{font-size:calc(1.3rem + .6vw)}
.h4,h4{font-size:calc(1.275rem + .3vw)}
.h5,h5{font-size:$(title.h5)}
.h6,h6{font-size:$(title.h6)}

.entry-title {
color: var(--jt-heading-color);
}
.entry-text h1,
.entry-text h2,
.entry-text h3,
.entry-text h4,
.entry-text h5,
.entry-text h6 {
color: var(--jt-heading-color);
padding-top: 1em;
margin-bottom: 1rem;
font-family:Google Sans Text;
}

.entry-text li {
margin-bottom: 0.5rem;
}

/* Responsive Style */

@media (min-width: 576px) {
.ratio-sm-4x3 {
padding-bottom: 75%;
}
.ratio-sm-16x9 {
padding-bottom: 56.25%;
}
.border-sm-end {
border-right-width: 1px !important;
